const body = $input.first().json;
const binary = $input.first().binary || {};
const files = [];
for (const [key, b] of Object.entries(binary)) {
  if (!b || !b.data) continue;
  const idx = key.replace(/\D/g,'') || '0';
  files.push({
    name: b.fileName || key,
    mimeType: b.mimeType || 'application/octet-stream',
    base64: b.data,
    docType: body['docType' + idx] || ''
  });
}
const raw = (body.prType || '').trim();
const map = {
  'Supply PR (APD)': 'APD',
  'Supply PR (Non-APD)': 'Non-APD',
  'Supply PR (FTP \u2013 First Time Purchase)': 'FTP',
  'PAC PR': 'PAC',
  'Service PR': 'Service'
};
return [{ json: {
  prType: map[raw] || raw,
  prNumber: (body.prNumber || '').trim(),
  itemLongText: (body.itemLongText || '').trim(),
  files
}}];

const data = $input.first().json;
const lines = (data.itemLongText || '').split('\n').filter(l => l.trim());
const drawings = {};
function normRev(r) {
  const c = (r || '').toUpperCase().trim();
  return (!c || /^0+$/.test(c) || c === 'NO REVISION') ? '0' : c;
}
for (const line of lines) {
  const clean = line.replace(/^APD,/i, '');
  const fields = {};
  clean.split(';').forEach(part => {
    const i = part.indexOf(':');
    if (i > 0) fields[part.slice(0,i).trim()] = part.slice(i+1).trim();
  });
  const dwg = (fields['DRAWING NUMBER'] || '').trim();
  if (!dwg) continue;
  if (!drawings[dwg]) {
    drawings[dwg] = {
      drawingNumber: dwg,
      revision: normRev(fields['REVISION']),
      itemName: fields['ITEM NAME'] || '',
      positions: [],
      material: fields['MATERIAL'] || fields['MATERIAL SPECIFICATION'] || null,
      prNumber: data.prNumber,
      files: data.files
    };
  }
  if (fields['POSITION OR ITEM NUMBER']) drawings[dwg].positions.push(fields['POSITION OR ITEM NUMBER']);
}
const list = Object.values(drawings);
if (list.length === 0) {
  return [{ json: { drawingNumber: 'UNKNOWN', revision: '0', positions: [], material: null, prNumber: data.prNumber, files: data.files, noDrawingsFound: true }}];
}
return list.map(d => ({ json: d }));

const data = $input.first().json;
const files = data.files || [];
const dwg = data.drawingNumber;
const match = files.find(f => f.name && f.name.toUpperCase().includes(dwg.toUpperCase()));
if (match) {
  return [{ json: { ...data, source: 'attachment', attachedFile: match }}];
} else {
  return [{ json: { ...data, source: 'missing', attachedFile: null }}];
}

const staticData = $getWorkflowStaticData('node');
if (!staticData.results) staticData.results = [];
const item = $input.first().json;
let result;
if (item.validationResult) {
  result = item.validationResult;
} else {
  result = {
    drawingNumber: item.drawingNumber,
    status: 'blocker_not_found',
    issues: [`Drawing ${item.drawingNumber} not found in Google Drive and no matching attachment uploaded`],
    notes: 'Blocker — attach the drawing to proceed'
  };
}
staticData.results.push(result);
return [{ json: { ...item, collected: true }}];

const staticData = $getWorkflowStaticData('node');
const results = staticData.results || [];
staticData.results = [];
const prNumber = ($input.first().json.prNumber) || '';
const blockers = results.filter(r => r.status === 'blocker_not_found' || (r.issues && r.issues.length > 0 && r.status !== 'confirmed_in_drive' && r.status !== 'validated_from_attachment'));
const warnings = results.filter(r => r.status === 'warning');
const allValid = blockers.length === 0;
const icons = { confirmed_in_drive:'✓', validated_from_attachment:'✓', warning:'⚠', blocker_not_found:'✗' };
const cardCls = { confirmed_in_drive:'pass', validated_from_attachment:'pass', warning:'warn', blocker_not_found:'fail' };
const statusTxt = { confirmed_in_drive:'Found in Google Drive — confirmed', validated_from_attachment:'Validated from uploaded attachment', warning:'Warning — review required', blocker_not_found:'BLOCKER — not found in Drive or as attachment' };
let html = `<div class="vr-block"><h3>APD PR #${prNumber} — Drawing Validation</h3>`;
html += `<div class="badge ${allValid?'pass':'fail'}">${allValid ? 'ALL DRAWINGS VALIDATED' : `${blockers.length} BLOCKER(S) · ${warnings.length} WARNING(S)`}</div>`;
results.forEach(r => {
  const icon = icons[r.status] || '?';
  const cc = cardCls[r.status] || '';
  const st = statusTxt[r.status] || r.status;
  html += `<div class="dr ${cc}"><h4>${icon} ${r.drawingNumber}</h4><p class="st">${st}</p>`;
  if (r.revisionMatch === false) html += `<p class="warn-txt">⚠ Revision mismatch</p>`;
  if (r.approvalStampPresent === false) html += `<p class="warn-txt">⚠ No approval stamp detected</p>`;
  if (r.materialFlag) html += `<p class="warn-txt">⚠ Material: ${r.materialFlag}</p>`;
  if (r.issues && r.issues.length) { html += `<ul class="iss">`; r.issues.forEach(i=>{ html+=`<li>${i}</li>`; }); html+=`</ul>`; }
  if (r.notes) html += `<p class="notes">${r.notes}</p>`;
  html += `</div>`;
});
const vt = allValid ? '✓ PR is ready to proceed' : `✗ PR has ${blockers.length} blocker(s) — resolve before submission`;
html += `<p class="verdict ${allValid?'pass':'fail'}">${vt}</p></div>`;
return [{ json: { responseHtml: html, prType: 'APD', prNumber, allValid }}];

const gemini = $input.first().json;
const ctx = $('FTP: Gemini Validate').item.json;
const prNumber = ctx.prNumber || '';
let r;
try {
  const txt = (gemini.candidates||[])[0]?.content?.parts?.[0]?.text || '{}';
  const m = txt.match(/\{[\s\S]*\}/); r = m ? JSON.parse(m[0]) : {};
} catch(e) { r = {}; }
const checks = [
  ['Cost breakdown present', r.hasCostBreakdown],
  ['Validity date present', r.hasValidityDate],
  ['Validity not expired', !r.isValidityExpired],
  ['Authorising signature', r.hasAuthorisingSignature]
];
const ok = r.hasCostBreakdown && r.hasValidityDate && !r.isValidityExpired && r.hasAuthorisingSignature;
let html = `<div class="vr-block"><h3>FTP PR #${prNumber} — Costing Sheet</h3>`;
html += `<div class="badge ${ok?'pass':'fail'}">${ok?'COSTING SHEET VALID':'COSTING SHEET HAS ISSUES'}</div>`;
if (r.validityDate) html += `<p class="meta">Validity date: <strong>${r.validityDate}</strong></p>`;
html += `<ul class="chk">`;
checks.forEach(([l,v])=>{ html+=`<li class="${v?'ok':'fail'}">${l}: ${v?'Yes':'No'}</li>`; });
html += `</ul>`;
if (r.issues && r.issues.length) { html+=`<ul class="iss">`; r.issues.forEach(i=>{html+=`<li>${i}</li>`;}); html+=`</ul>`; }
const vt = ok ? '✓ PR is ready to proceed' : '✗ PR has blockers — resolve before submission';
html += `<p class="verdict ${ok?'pass':'fail'}">${vt}</p></div>`;
return [{ json: { responseHtml: html, prType: 'FTP', prNumber, allValid: ok }}];

const gemini = $input.first().json;
const ctx = $('PAC: Gemini Validate').item.json;
const prNumber = ctx.prNumber || '';
let r;
try {
  const txt = (gemini.candidates||[])[0]?.content?.parts?.[0]?.text || '{}';
  const m = txt.match(/\{[\s\S]*\}/); r = m ? JSON.parse(m[0]) : {};
} catch(e) { r = {}; }
const ok = !r.isExpired && !r.expiresWithin30Days && r.hasSignature && !!r.certNumber && !!r.vendorName;
const checks = [
  ['Certificate number present', !!r.certNumber],
  ['Vendor name present', !!r.vendorName],
  ['Certificate current (not expired)', !r.isExpired],
  ['Not expiring within 30 days', !r.expiresWithin30Days],
  ['Authorising signature', r.hasSignature]
];
let html = `<div class="vr-block"><h3>PAC PR #${prNumber} — Certificate Validation</h3>`;
html += `<div class="badge ${ok?'pass':'fail'}">${ok?'CERTIFICATE VALID':'CERTIFICATE HAS ISSUES'}</div>`;
if (r.vendorName) html += `<p class="meta">Vendor: <strong>${r.vendorName}</strong></p>`;
if (r.certNumber) html += `<p class="meta">Cert #: <strong>${r.certNumber}</strong></p>`;
if (r.expiryDate) html += `<p class="meta">Expiry: <strong>${r.expiryDate}</strong>${r.isExpired?' <span style="color:#dc2626">— EXPIRED</span>':r.expiresWithin30Days?' <span style="color:#b45309">— expires soon</span>':''}</p>`;
html += `<ul class="chk">`;
checks.forEach(([l,v])=>{ html+=`<li class="${v?'ok':'fail'}">${l}: ${v?'Yes':'No'}</li>`; });
html += `</ul>`;
if (r.issues && r.issues.length) { html+=`<ul class="iss">`; r.issues.forEach(i=>{html+=`<li>${i}</li>`;}); html+=`</ul>`; }
const vt = ok ? '✓ PR is ready to proceed' : '✗ PR has blockers — resolve before submission';
html += `<p class="verdict ${ok?'pass':'fail'}">${vt}</p></div>`;
return [{ json: { responseHtml: html, prType: 'PAC', prNumber, allValid: ok }}];

const data = $input.first().json;
const files = data.files || [];
const prNumber = data.prNumber;
const sow = files.find(f => (f.docType||'').toLowerCase().includes('scope'));
const jsa = files.find(f => (f.docType||'').toLowerCase().includes('jsa') || (f.docType||'').toLowerCase().includes('job safety'));
const tech = files.find(f => (f.docType||'').toLowerCase().includes('technical') || (f.docType||'').toLowerCase().includes('skill'));
const missing = [];
if (!sow) missing.push('Scope of Work');
if (!jsa) missing.push('Job Safety Analysis (JSA)');
if (!tech) missing.push('Technical Skill-Set');
return [{ json: { ...data, sowFile: sow||null, jsaFile: jsa||null, techFile: tech||null, missingDocs: missing, hasAllDocs: missing.length === 0 }}];

const gemini = $input.first().json;
const ctx = $('Service: Gemini Validate All').item.json;
const prNumber = ctx.prNumber || '';
let r;
try {
  const txt = (gemini.candidates||[])[0]?.content?.parts?.[0]?.text || '{}';
  const m = txt.match(/\{[\s\S]*\}/); r = m ? JSON.parse(m[0]) : {};
} catch(e) { r = {}; }
const sow = r.scopeOfWork || {}; const jsa = r.jsa || {}; const tech = r.technicalSkillSet || {}; const cc = r.crossCheck || {};
const ok = (sow.hasDeliverables && sow.hasTimeline && sow.hasAcceptanceCriteria) && (jsa.identifiesHazards && jsa.hasControlMeasures && jsa.hasSafetySignature) && tech.listsQualifications && cc.consistent;
const sec = (title, checks) => {
  let h = `<div class="doc-sec"><h4>${title}</h4><ul class="chk">`;
  checks.forEach(([l,v])=>{ h+=`<li class="${v?'ok':'fail'}">${l}: ${v?'Yes':'No'}</li>`; });
  return h + '</ul></div>';
};
let html = `<div class="vr-block"><h3>Service PR #${prNumber} — Document Validation</h3>`;
html += `<div class="badge ${ok?'pass':'fail'}">${ok?'ALL DOCUMENTS VALID':'DOCUMENTS REQUIRE ATTENTION'}</div>`;
html += sec('Scope of Work', [['Deliverables specified', sow.hasDeliverables], ['Timeline/duration present', sow.hasTimeline], ['Acceptance criteria defined', sow.hasAcceptanceCriteria]]);
html += sec('Job Safety Analysis', [['Hazards identified', jsa.identifiesHazards], ['Control measures specified', jsa.hasControlMeasures], ['Safety officer signature', jsa.hasSafetySignature]]);
html += sec('Technical Skill-Set', [['Qualifications/certs listed', tech.listsQualifications]]);
html += sec('Cross-Document Consistency', [['Documents consistent', cc.consistent]]);
if (cc.inconsistencies && cc.inconsistencies.length) { html+=`<ul class="iss">`; cc.inconsistencies.forEach(i=>{html+=`<li>${i}</li>`;}); html+=`</ul>`; }
const allIssues = [...(sow.issues||[]), ...(jsa.issues||[]), ...(tech.issues||[])];
if (allIssues.length) { html+=`<ul class="iss">`; allIssues.forEach(i=>{html+=`<li>${i}</li>`;}); html+=`</ul>`; }
const vt = ok ? '✓ PR is ready to proceed' : '✗ PR has blockers — resolve before submission';
html += `<p class="verdict ${ok?'pass':'fail'}">${vt}</p></div>`;
return [{ json: { responseHtml: html, prType: 'Service', prNumber, allValid: ok }}];
